import json
import os
import re
import argparse

import numpy as np
import pandas as pd
from abc import ABC

from common.utils.time import unix_to_timestamps
from server.storage.base import DataReader, RCSBaseWriter
from server.settings import RCS_EVENTS_FILENAME

class EventSpec(ABC):
    group_name = "Events"
    dataset_name = "EventLog"
    time_name = "Timestamps"


class EventReader(EventSpec, DataReader):
    """Wrapper class for reading event data from the HDF5 file"""


class EventWriter(EventSpec, RCSBaseWriter):
    """Wrapper class for writing new event data to an HDF5 file"""

    chunk_spec = (None, )
    dim_names = ['Time', 'Side', 'Location', 'Channel']
    dim_labels = [
        ['Replace', 'With', 'Timestamps'],
        ['Side', 'Event Type', 'Description']
    ]

    @classmethod
    def from_sources(cls, left_source, right_source, target_loc, filename=RCS_EVENTS_FILENAME):
        return super(EventWriter, cls).from_sources(left_source, right_source, target_loc, filename)

    @classmethod
    def from_stack(cls, writers):
        """
        Concatenate a time-ordered sequence of data writers of the same type together
        """
        as_df = pd.concat([pd.DataFrame.from_records(w._data, index=w._timestamps) for w in writers], axis=0)
        unindexed = as_df.reset_index()
        unindexed.drop_duplicates(keep='first', inplace=True)
        stacked = unindexed.set_index('timestamp')

        attributes = cls.stack_attrs(writers)

        return cls.from_ready(writers[0].file_location, stacked.index, stacked.values, attributes)

    def select_side(self, side_data, side):
        """Select all the events for one side"""
        subset = pd.DataFrame.from_dict({
            'Side': [side] * len(side_data),
            'Event Time': np.array(side_data['EventType']),
            'Description': np.array(side_data['EventSubType'])
        })
        subset.index = side_data.index
        return subset

    def prep_data(self):
        """
        Unique version of prep_data to handle sporadic events

        Since events are sporadic, we can't expect any kind of regular sampling frequency. Therefore, we can only stack
        the data vertically, and have to keep track of the side in a column
        """
        self.left_data = self.select_side(self.left_data, 'Left')
        self.right_data = self.select_side(self.right_data, 'Right')

        l_offset = self.left_offset if self.left_offset else pd.Timedelta(seconds=0)
        r_offset = self.right_offset if self.right_offset else pd.Timedelta(seconds=0)

        self.left_data.index = unix_to_timestamps(self.left_data.index) + l_offset
        self.right_data.index = unix_to_timestamps(self.right_data.index) + r_offset

        stacked_data = pd.concat([self.left_data, self.right_data], axis=0)
        stacked_data.sort_index(axis='index')
        return stacked_data.index, stacked_data.values.astype('S')

    def prep_attributes(self):
        return super(EventWriter, self).prep_attributes()
